use gg_compiler_core::artifact::{Artifact, ArtifactKey}; use gg_compiler_core::context::{BuildConfig, BuildContext}; use gg_compiler_core::pipeline::{Pipeline, ArtifactSet}; use gg_compiler_core::transformer::Transformer; use std::sync::{Arc, Mutex}; /// 记录执行顺序的简单转换器 struct RecordingTransformer { /// 转换器名称 name: String, /// 执行记录共享引用 log: Arc<Mutex<Vec<String>>>, } impl RecordingTransformer { /// 创建新的记录转换器 fn new(name: &str, log: Arc<Mutex<Vec<String>>>) -> Self { Self { name: name.to_string(), log, } } } impl Transformer for RecordingTransformer { fn name(&self) -> &str { &self.name } fn input_keys(&self) -> Vec<ArtifactKey> { vec![] } fn output_keys(&self) -> Vec<ArtifactKey> { vec![ArtifactKey::new("output", &self.name)] } fn transform( &self, _inputs: &ArtifactSet, _context: &mut BuildContext, ) -> GResult<ArtifactSet> { self.log.lock().unwrap().push(self.name.clone()); let mut output = ArtifactSet::new(); output.insert(Artifact::new( ArtifactKey::new("output", &self.name), vec![self.name.len() as u8], )); Ok(output) } } /// 测试线性流水线（A -> B -> C）按顺序执行 #[test] fn test_linear_pipeline_execution_order() { let log = Arc::new(Mutex::new(Vec::new())); let mut pipeline = Pipeline::new(); pipeline.add_node( "a", Box::new(RecordingTransformer::new("a", Arc::clone(&log))), vec![], ); pipeline.add_node( "b", Box::new(RecordingTransformer::new("b", Arc::clone(&log))), vec!["a".to_string()], ); pipeline.add_node( "c", Box::new(RecordingTransformer::new("c", Arc::clone(&log))), vec!["b".to_string()], ); let mut context = BuildContext::new(BuildConfig::new()); let result = pipeline.execute(ArtifactSet::new(), &mut context); assert!(result.is_ok()); let recorded = log.lock().unwrap().clone(); assert_eq!(recorded, vec!["a", "b", "c"]); } /// 测试菱形流水线（A -> B, A -> C, B -> D, C -> D）依赖关系 #[test] fn test_diamond_pipeline_respects_dependencies() { let log = Arc::new(Mutex::new(Vec::new())); let mut pipeline = Pipeline::new(); pipeline.add_node( "a", Box::new(RecordingTransformer::new("a", Arc::clone(&log))), vec![], ); pipeline.add_node( "b", Box::new(RecordingTransformer::new("b", Arc::clone(&log))), vec!["a".to_string()], ); pipeline.add_node( "c", Box::new(RecordingTransformer::new("c", Arc::clone(&log))), vec!["a".to_string()], ); pipeline.add_node( "d", Box::new(RecordingTransformer::new("d", Arc::clone(&log))), vec!["b".to_string(), "c".to_string()], ); let mut context = BuildContext::new(BuildConfig::new()); let result = pipeline.execute(ArtifactSet::new(), &mut context); assert!(result.is_ok()); let recorded = log.lock().unwrap().clone(); assert_eq!(recorded[0], "a"); assert!(recorded.contains(&"b".to_string())); assert!(recorded.contains(&"c".to_string())); assert_eq!(recorded[3], "d"); let b_pos = recorded.iter().position(|x| x == "b").unwrap(); let c_pos = recorded.iter().position(|x| x == "c").unwrap(); let d_pos = recorded.iter().position(|x| x == "d").unwrap(); assert!(b_pos < d_pos); assert!(c_pos < d_pos); } /// 测试循环依赖检测 #[test] fn test_circular_dependency_detection() { let log = Arc::new(Mutex::new(Vec::new())); let mut pipeline = Pipeline::new(); pipeline.add_node( "a", Box::new(RecordingTransformer::new("a", Arc::clone(&log))), vec!["b".to_string()], ); pipeline.add_node( "b", Box::new(RecordingTransformer::new("b", Arc::clone(&log))), vec!["a".to_string()], ); let result = pipeline.topological_sort(); assert!(result.is_err()); } /// 测试增量编译：相同输入时跳过未变化的节点 #[test] fn test_incremental_compilation_skips_unchanged() { let log = Arc::new(Mutex::new(Vec::new())); let mut pipeline = Pipeline::new(); pipeline.add_node( "a", Box::new(RecordingTransformer::new("a", Arc::clone(&log))), vec![], ); pipeline.add_node( "b", Box::new(RecordingTransformer::new("b", Arc::clone(&log))), vec!["a".to_string()], ); 